<section class="hero" id="sorteos" aria-label="Sorteos activos" data-carousel>
<?php if(!$raffles): ?><div class="hero-slide no-raffles"><div class="hero-copy"><span class="hero-kicker">BIENVENIDO A SORTEOWEB</span><h1>Tu próxima oportunidad comienza aquí.</h1><p>Descubre nuevos premios y consulta nuestros sorteos cuando estén disponibles.</p><a class="pub-btn cta" href="<?=h(pub_url($u?'account':'login'))?>">¡PARTICIPA YA! <span aria-hidden="true">→</span></a></div><div class="hero-empty" aria-hidden="true">★</div></div><?php else: ?>
